import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;
import org.apache.commons.text.StringEscapeUtils;

public class ReportServlet extends HttpServlet {

    private static final Pattern SAFE_ORDER_PATTERN = Pattern.compile("^[a-zA-Z_]+$");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String dateFrom = req.getParameter("from");
        String dateTo = req.getParameter("to");
        String sortCol = req.getParameter("sort");
        String filterExpr = req.getParameter("filter");

        // Validate report type
        if (reportType == null || !reportType.matches("(sales|inventory|audit)")) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate date format
        if (dateFrom != null && !dateFrom.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date format");
            return;
        }
        if (dateTo != null && !dateTo.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date format");
            return;
        }

        // Sort column validation - allow dotted notation for joined tables
        if (sortCol != null && !sortCol.matches("^[a-zA-Z_][a-zA-Z0-9_.]*$")) {
            sortCol = "created_at";
        }

        // Build query - dates are validated above, sort is regex-checked
        StringBuilder query = new StringBuilder();
        query.append("SELECT * FROM ").append(reportType).append("_reports");
        query.append(" WHERE created_at >= '").append(dateFrom).append("'");
        query.append(" AND created_at <= '").append(dateTo).append("'");

        // Advanced filter - allows power users to specify conditions
        // We escape HTML entities to prevent XSS in error messages
        if (filterExpr != null && !filterExpr.isEmpty()) {
            String sanitized = filterExpr.replaceAll(";", "")
                                         .replaceAll("--", "")
                                         .replaceAll("/\\*", "")
                                         .replaceAll("\\*/", "")
                                         .replaceAll("xp_", "")
                                         .replaceAll("UNION", "", Pattern.CASE_INSENSITIVE)
                                         .replaceAll("DROP", "", Pattern.CASE_INSENSITIVE)
                                         .replaceAll("INSERT", "", Pattern.CASE_INSENSITIVE)
                                         .replaceAll("DELETE", "", Pattern.CASE_INSENSITIVE)
                                         .replaceAll("UPDATE", "", Pattern.CASE_INSENSITIVE);
            query.append(" AND (").append(sanitized).append(")");
        }

        if (sortCol != null) {
            query.append(" ORDER BY ").append(sortCol);
        }
        query.append(" LIMIT 1000");

        Connection conn = null;
        Statement stmt = null;
        try {
            conn = getConnection();
            stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(query.toString());

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print(resultSetToJson(rs));

        } catch (SQLException e) {
            // Log sanitized error
            String safeMsg = StringEscapeUtils.escapeHtml4(e.getMessage());
            resp.sendError(500, "Query error: " + safeMsg);
        } finally {
            if (stmt != null) try { stmt.close(); } catch (SQLException e) {}
            if (conn != null) try { conn.close(); } catch (SQLException e) {}
        }
    }

    private Connection getConnection() throws SQLException {
        String url = System.getenv("JDBC_URL");
        String user = System.getenv("DB_USER");
        String pass = System.getenv("DB_PASS");
        return DriverManager.getConnection(url, user, pass);
    }

    private String resultSetToJson(ResultSet rs) throws SQLException {
        StringBuilder json = new StringBuilder("[");
        ResultSetMetaData meta = rs.getMetaData();
        int cols = meta.getColumnCount();
        boolean first = true;
        while (rs.next()) {
            if (!first) json.append(",");
            json.append("{");
            for (int i = 1; i <= cols; i++) {
                if (i > 1) json.append(",");
                json.append("\"").append(meta.getColumnName(i)).append("\":");
                json.append("\"").append(rs.getString(i)).append("\"");
            }
            json.append("}");
            first = false;
        }
        json.append("]");
        return json.toString();
    }
}
